"""Helpdesk CLI entry point."""

import sys
from helpdesk.cli import build_parser
from helpdesk.db import init_db
from helpdesk.agents import add_agent, agent_workload
from helpdesk.tickets import (
    ticket_open,
    ticket_assign,
    ticket_comment,
    ticket_close,
    ticket_list,
)
from helpdesk.sla import sla_report


def main() -> None:
    parser = build_parser()
    args = parser.parse_args()

    dispatch_map = {
        ("init",): lambda: init_db(args.db),
        ("agent", "add"): lambda: add_agent(args.db, args.name),
        ("agent", "workload"): lambda: agent_workload(
            args.db, args.name, args.today
        ),
        ("ticket", "open"): lambda: ticket_open(
            init_db(args.db), args.title, args.priority, args.assignee
        ),
        ("ticket", "assign"): lambda: ticket_assign(
            init_db(args.db), args.ticket_id, args.agent_name
        ),
        ("ticket", "comment"): lambda: ticket_comment(
            init_db(args.db), args.ticket_id, args.text
        ),
        ("ticket", "close"): lambda: ticket_close(
            init_db(args.db), args.ticket_id, args.resolution
        ),
        ("ticket", "list"): lambda: ticket_list(
            init_db(args.db), args.status, args.assignee, args.priority
        ),
        ("sla", "report"): lambda: sla_report(args.db, args.today),
    }

    if args.command == "init":
        key = ("init",)
    else:
        action_attr = f"{args.command}_action"
        key = (args.command, getattr(args, action_attr))

    handler = dispatch_map.get(key)
    if handler is None:
        print(f"Error: Unknown command '{args.command}'", file=sys.stderr)
        sys.exit(1)

    try:
        handler()
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()
